1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ScenarioOutcome = {
6	  results: QuoteResult[];
7	};
8	
9	type Item = { type: string };
10	
11	type Scenario = {
12	  steps: { items: Item[] }[];
13	};
14	
15	const PROCESSING_FEE = 5;
16	const FIRST_INSURANCE_SURCHARGE = 0.1;
17	
18	const BASE_PREMIUMS: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	  rune: 25,
24	  moonstone: 25,
25	};
26	
27	const basePremiumOf = (items: Item[]): number =>
28	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
29	
30	const quotePremium = (items: Item[]): number => {
31	  const base = basePremiumOf(items);
32	  const withFirstInsuranceSurcharge = base + base * FIRST_INSURANCE_SURCHARGE;
33	
34	  return Math.ceil(withFirstInsuranceSurcharge + PROCESSING_FEE);
35	};
36	
37	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
38	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
39	});
